<?php
session_start();
$pdo=new PDO('mysql:host=127.0.0.1;charset=utf8mb4','root','',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$pdo->exec("CREATE DATABASE IF NOT EXISTS parking_garage CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci"); $pdo->exec('USE parking_garage');
$pdo->exec("CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,phone VARCHAR(30),password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$pdo->exec("CREATE TABLE IF NOT EXISTS admins(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$pdo->exec("CREATE TABLE IF NOT EXISTS parking_slots(id INT AUTO_INCREMENT PRIMARY KEY,slot_code VARCHAR(30) UNIQUE NOT NULL,floor VARCHAR(50) DEFAULT 'Ground Floor',zone VARCHAR(30) DEFAULT 'A',vehicle_type VARCHAR(30) DEFAULT 'Any',hourly_rate DECIMAL(10,2) DEFAULT 30,status ENUM('Available','Occupied','Maintenance') DEFAULT 'Available',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$pdo->exec("CREATE TABLE IF NOT EXISTS parking_sessions(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,slot_id INT NOT NULL,vehicle_number VARCHAR(30) NOT NULL,vehicle_type VARCHAR(30) NOT NULL,entry_time DATETIME NOT NULL,exit_time DATETIME NULL,amount DECIMAL(10,2) NULL,status ENUM('Active','Completed') DEFAULT 'Active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(slot_id) REFERENCES parking_slots(id))");
if(!(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()){$s=$pdo->prepare('INSERT INTO admins(name,email,password) VALUES(?,?,?)');$s->execute(['Garage Admin','admin@parkora.local',password_hash('password',PASSWORD_DEFAULT)]);}
if(!(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn()){$s=$pdo->prepare('INSERT INTO users(name,email,phone,password) VALUES(?,?,?,?)');$s->execute(['Demo Driver','driver@parkora.local','9876543210',password_hash('password',PASSWORD_DEFAULT)]);}
if(!(int)$pdo->query('SELECT COUNT(*) FROM parking_slots')->fetchColumn()){$s=$pdo->prepare('INSERT INTO parking_slots(slot_code,floor,zone,vehicle_type,hourly_rate) VALUES(?,?,?,?,?)');foreach([['A-01','Ground Floor','A','Car',40],['A-02','Ground Floor','A','Car',40],['A-03','Ground Floor','A','SUV',50],['B-01','Ground Floor','B','Bike',20],['B-02','Ground Floor','B','Bike',20],['C-01','First Floor','C','EV',60],['C-02','First Floor','C','EV',60],['C-03','First Floor','C','Any',45]] as $x)$s->execute($x);}
function e($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');} function user_required(){if(empty($_SESSION['user_id'])){header('Location: user_login.php');exit;}} function admin_required(){if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}} function go($x){header('Location: '.$x);exit;}
?>
